name = "harry is good boy"

print(len(name))
print(name.endswith("ry"))
print(name.startswith("harry"))
print(name.capitalize())
print(name.title())
print(name.upper())

# strings are not mutable, here the changes do not edit the strings but create new string with the changes. 
# hence string cannot be edited and here new string is created with desired changes.